请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-008

=== 用户原始指令 (query.txt) ===
搞个清理空间的卡片吧，要有几项可以打勾选，显示一行带数字的话，点一下能进入系统操作，要有红色危险提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个清理空间的卡片吧，要有几项可以打勾选，显示一行带数字的话，点一下能进入系统操作，要有红色危险提示",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "storage_settings"
      }
    }
  ],
  "dataModelSchema": {
    "card": {
      "title": {
        "type": "string",
        "description": "内存清理卡片标题",
        "sampleValue": "清理空间"
      },
      "alertText": {
        "type": "string",
        "description": "危险状态短提示",
        "sampleValue": "危险"
      }
    },
    "items": {
      "cache": {
        "label": {
          "type": "string",
          "description": "缓存清理勾选项名称",
          "sampleValue": "缓存"
        },
        "sizeText": {
          "type": "string",
          "description": "缓存可清理空间展示值",
          "sampleValue": "2.8GB"
        },
        "selected": {
          "type": "boolean",
          "description": "缓存清理项是否默认选中",
          "sampleValue": true
        }
      },
      "packages": {
        "label": {
          "type": "string",
          "description": "安装包清理勾选项名称",
          "sampleValue": "安装包"
        },
        "sizeText": {
          "type": "string",
          "description": "安装包可清理空间展示值",
          "sampleValue": "0.8GB"
        },
        "selected": {
          "type": "boolean",
          "description": "安装包清理项是否默认选中",
          "sampleValue": true
        }
      }
    },
    "summary": {
      "actionText": {
        "type": "string",
        "description": "进入系统存储操作的短入口文案",
        "sampleValue": "可清理"
      },
      "reclaimText": {
        "type": "string",
        "description": "合计可清理空间数字展示",
        "sampleValue": "3.6GB"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_clear.png",
      "description": "清除图标，适合表达清理空间、清除缓存或释放存储的入口识别。"
    }
  ]
}

